*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --color-bg:           #f5f6fa;
  --color-surface:      #ffffff;
  --color-border:       #d1d5db;
  --color-border-focus: #2563eb;
  --color-text:         #111827;
  --color-text-muted:   #6b7280;
  --color-label:        #374151;
  --color-primary:      #2563eb;
  --color-primary-dark: #1d4ed8;
  --color-error:        #b91c1c;
  --color-error-bg:     #fef2f2;
  --color-error-border: #fca5a5;
  --color-success:      #065f46;
  --color-success-bg:   #ecfdf5;
  --color-success-border: #6ee7b7;
  --color-required:     #b91c1c;
  --radius:             8px;
  --shadow:             0 1px 3px rgba(0,0,0,.10), 0 1px 2px rgba(0,0,0,.06);
  --shadow-lg:          0 10px 25px rgba(0,0,0,.08), 0 4px 10px rgba(0,0,0,.05);
  --transition:         0.15s ease;
}

html { font-size: 16px; }

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem 1rem;
  line-height: 1.5;
}

/* ── Skip link ─────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: 0.5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  border-radius: 0 0 var(--radius) var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 999;
  transition: top var(--transition);
}
.skip-link:focus { top: 0; }

/* ── Page layout ───────────────────────────────────────────── */
.page-header {
  text-align: center;
  margin-bottom: 2rem;
  max-width: 480px;
  width: 100%;
}

.page-header h1 {
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 700;
  color: var(--color-text);
  letter-spacing: -0.01em;
  margin-bottom: 0.5rem;
}

.page-header p {
  color: var(--color-text-muted);
  font-size: 1rem;
}

main {
  width: 100%;
  max-width: 480px;
}

/* ── Card ──────────────────────────────────────────────────── */
.form-card {
  background: var(--color-surface);
  border-radius: 12px;
  box-shadow: var(--shadow-lg);
  padding: clamp(1.5rem, 5vw, 2.5rem);
}

/* ── Required legend ───────────────────────────────────────── */
.required-note {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  margin-bottom: 1.5rem;
}
.required-note .req-marker { color: var(--color-required); font-weight: 700; }

/* ── Form fields ───────────────────────────────────────────── */
.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  margin-bottom: 1.25rem;
}

.form-field:last-of-type { margin-bottom: 1.75rem; }

label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-label);
}

.req-star { color: var(--color-required); margin-left: 0.1em; }

input[type="text"],
input[type="email"],
input[type="tel"] {
  padding: 0.625rem 0.875rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius);
  font-size: 1rem;
  font-family: inherit;
  color: var(--color-text);
  background: #fff;
  transition: border-color var(--transition), box-shadow var(--transition);
  width: 100%;
}

input:focus {
  outline: none;
  border-color: var(--color-border-focus);
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.20);
}

input[aria-invalid="true"] {
  border-color: var(--color-error);
  background: var(--color-error-bg);
}

input[aria-invalid="true"]:focus {
  border-color: var(--color-error);
  box-shadow: 0 0 0 3px rgba(185, 28, 28, 0.18);
}

/* ── Help & error text ─────────────────────────────────────── */
.field-help {
  font-size: 0.8125rem;
  color: var(--color-text-muted);
  line-height: 1.4;
}

.field-error {
  font-size: 0.8125rem;
  color: var(--color-error);
  font-weight: 500;
  line-height: 1.4;
  display: none;
}

.field-error[aria-hidden="false"],
.field-error:not([hidden]) { display: block; }

/* ── Submit button ─────────────────────────────────────────── */
.btn-submit {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  padding: 0.75rem 1.5rem;
  background: var(--color-primary);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition), box-shadow var(--transition);
  letter-spacing: 0.01em;
}

.btn-submit:hover { background: var(--color-primary-dark); }

.btn-submit:focus-visible {
  outline: none;
  box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.40);
}

.btn-submit:active { transform: translateY(1px); }

/* ── Status messages ───────────────────────────────────────── */
#form-status {
  margin-top: 1.25rem;
  padding: 0.875rem 1rem;
  border-radius: var(--radius);
  font-size: 0.9375rem;
  font-weight: 500;
  display: none;
}

#form-status.success {
  display: block;
  color: var(--color-success);
  background: var(--color-success-bg);
  border: 1.5px solid var(--color-success-border);
}

#form-status.error {
  display: block;
  color: var(--color-error);
  background: var(--color-error-bg);
  border: 1.5px solid var(--color-error-border);
}

/* ── Forced colors (Windows High Contrast) ─────────────────── */
@media (forced-colors: active) {
  input { border: 2px solid ButtonText; }
  input:focus { outline: 2px solid Highlight; }
  .btn-submit { forced-color-adjust: none; background: ButtonFace; color: ButtonText; border: 2px solid ButtonText; }
  .field-error { color: LinkText; }
}

/* ── Reduced motion ────────────────────────────────────────── */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { transition: none !important; }
}

/* ── Reflow @ 320 px ───────────────────────────────────────── */
@media (max-width: 380px) {
  .form-card { padding: 1.25rem 1rem; }
}
