 /* app.js – contact form validation */
 (function () {
   'use strict';

   const form = document.getElementById('contact-form');
   const formStatus = document.getElementById('form-status');

   /* ── Validation rules ─────────────────────────────────────── */
   const fields = {
     name: {
       input: document.getElementById('name'),
       error: document.getElementById('name-error'),
       validate(val) {
         if (!val.trim()) return 'Error: Full name is required.';
         if (val.trim().length < 2) return 'Error: Enter your full name (at least 2 characters).';
         return null;
       },
     },
     email: {
       input: document.getElementById('email'),
       error: document.getElementById('email-error'),
       validate(val) {
         if (!val.trim()) return 'Error: Email address is required.';
         /* RFC-5322-ish pattern — catches common mistakes */
         if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(val.trim())) {
           return 'Error: Enter a valid email address, e.g. you@example.com.';
         }
         return null;
       },
     },
     phone: {
       input: document.getElementById('phone'),
       error: document.getElementById('phone-error'),
       validate(val) {
         if (!val.trim()) return null; /* optional */
         /* Allow digits, spaces, dashes, dots, parentheses, leading + */
         if (!/^\+?[\d\s\-().]{7,20}$/.test(val.trim())) {
           return 'Error: Enter a valid phone number, e.g. +1 (555) 000-0000.';
         }
         return null;
       },
     },
   };

   /* ── Helpers ──────────────────────────────────────────────── */
   function showError(field, message) {
     field.input.setAttribute('aria-invalid', 'true');
     field.error.textContent = message;
     field.error.style.display = 'block';
   }

   function clearError(field) {
     field.input.removeAttribute('aria-invalid');
     field.error.textContent = '';
     field.error.style.display = 'none';
   }

   function validateField(key) {
     const field = fields[key];
     const msg = field.validate(field.input.value);
     if (msg) { showError(field, msg); return false; }
     clearError(field);
     return true;
   }

   /* ── Inline validation on blur ────────────────────────────── */
   Object.keys(fields).forEach(key => {
     fields[key].input.addEventListener('blur', () => validateField(key));
     /* Clear error eagerly as user types after a failed attempt */
     fields[key].input.addEventListener('input', () => {
       if (fields[key].input.getAttribute('aria-invalid') === 'true') {
         validateField(key);
       }
     });
   });

   /* ── Submit ───────────────────────────────────────────────── */
   form.addEventListener('submit', function (e) {
     e.preventDefault();

     /* Reset status */
     formStatus.className = '';
     formStatus.style.display = 'none';
     formStatus.textContent = '';

     const results = Object.keys(fields).map(k => validateField(k));
     const allValid = results.every(Boolean);

     if (!allValid) {
       /* Focus first invalid field */
       const firstInvalidKey = Object.keys(fields).find(k => !results[Object.keys(fields).indexOf(k)]);
       if (firstInvalidKey) fields[firstInvalidKey].input.focus();

       /* Announce error count via alert role (focus already moved, so use status) */
       const errorCount = results.filter(r => !r).length;
       formStatus.textContent = `Please fix ${errorCount} error${errorCount > 1 ? 's' : ''} before sending.`;
       formStatus.className = 'error';
       formStatus.style.display = 'block';
       return;
     }

     /* Simulate successful submission */
     formStatus.textContent = 'Your message has been sent. We\'ll be in touch soon.';
     formStatus.className = 'success';
     formStatus.style.display = 'block';
     form.reset();
     Object.keys(fields).forEach(k => clearError(fields[k]));
   });
 }());

